import os
from typing import Iterable, List, Optional, Dict, Any

from google.cloud import pubsub_v1


def publish_batch(
    project_id: str,
    topic_id: str,
    messages: Iterable[Dict[str, Any]],
    ordering_key: Optional[str] = None,
) -> List[str]:
    publisher = pubsub_v1.PublisherClient()
    topic_path = publisher.topic_path(project_id, topic_id)

    future_to_message_id = []

    for item in messages:
        data = item.get("data", b"")
        if isinstance(data, str):
            data = data.encode("utf-8")
        elif not isinstance(data, (bytes, bytearray)):
            data = str(data).encode("utf-8")

        attributes = {str(k): str(v) for k, v in item.get("attributes", {}).items()}

        message_ordering_key = item.get("ordering_key", ordering_key)
        if message_ordering_key is not None:
            future = publisher.publish(
                topic_path,
                bytes(data),
                ordering_key=str(message_ordering_key),
                **attributes,
            )
        else:
            future = publisher.publish(topic_path, bytes(data), **attributes)

        future_to_message_id.append(future)

    return [future.result() for future in future_to_message_id]


if __name__ == "__main__":
    project = os.environ["GOOGLE_CLOUD_PROJECT"]
    topic = os.environ["PUBSUB_TOPIC_ID"]

    batch = [
        {
            "data": "event-1",
            "attributes": {"message_id": "msg-001", "source": "billing"},
        },
        {
            "data": "event-2",
            "attributes": {"message_id": "msg-002", "source": "orders"},
        },
        {
            "data": b'{"type":"user.created","id":"u_123"}',
            "attributes": {"message_id": "msg-003", "content_type": "application/json"},
        },
    ]

    published_ids = publish_batch(project, topic, batch)
    print(published_ids)
